import type { HTMLAttributes } from 'react'

import { cx } from '~/lib/cx'

import styles from './button-group.module.scss'

export interface ButtonGroupProps extends HTMLAttributes<HTMLDivElement> {
  orientation?: 'horizontal' | 'vertical'
  /** Join the buttons into one continuous control. */
  attached?: boolean
}

/** Groups related buttons into one visual unit. */
export function ButtonGroup({
  orientation = 'horizontal',
  attached = true,
  className,
  children,
  ...props
}: ButtonGroupProps) {
  return (
    <div
      role="group"
      className={cx(
        styles.root,
        orientation === 'vertical' ? styles.vertical : styles.horizontal,
        attached && styles.attached,
        className,
      )}
      {...props}
    >
      {children}
    </div>
  )
}

@use 'styles' as vz;

.root {
  display: inline-flex;
  align-items: stretch;
}

.horizontal {
  flex-direction: row;
}

.vertical {
  flex-direction: column;
}

.root.attached > * {
  border-radius: 0;
}

.root.attached.horizontal > * + * {
  margin-inline-start: -1px;
}

.root.attached.vertical > * + * {
  margin-block-start: -1px;
}

.root.attached.horizontal > *:first-child {
  border-start-start-radius: var(--btn-radius, #{vz.radius('lg')});
  border-end-start-radius: var(--btn-radius, #{vz.radius('lg')});
}

.root.attached.horizontal > *:last-child {
  border-start-end-radius: var(--btn-radius, #{vz.radius('lg')});
  border-end-end-radius: var(--btn-radius, #{vz.radius('lg')});
}

.root.attached.vertical > *:first-child {
  border-start-start-radius: var(--btn-radius, #{vz.radius('lg')});
  border-start-end-radius: var(--btn-radius, #{vz.radius('lg')});
}

.root.attached.vertical > *:last-child {
  border-end-start-radius: var(--btn-radius, #{vz.radius('lg')});
  border-end-end-radius: var(--btn-radius, #{vz.radius('lg')});
}
